				target = args[0]
			}
			return runSemanticGC(cmd.Context(), cmd, opts, target, olderThan)
		},
	}
	cmd.Flags().StringVar(&olderThan, "older-than", "30d", "Prune semantic snapshots older than this duration")
	return cmd
